// 종이 세금계산서 OCR 상자 견본(시험·화면 갤러리 공용). 실제 사업자 정보가 아니다(사업자번호는 검증 숫자만 맞춘 가짜).
import type { OcrBox } from '../../src/capture/invoice.ts';

const H = 0.018;
const B = (text: string, x: number, y: number, w = 0.08): OcrBox => ({ text, x, y, w, h: H });

/** 공급받는자 보관용 종이 세금계산서(별지 제14호 모양). 왼쪽 공급자, 오른쪽 공급받는자. */
export function paperTaxInvoice(opts: { digitCells?: boolean; noLabels?: boolean } = {}): OcrBox[] {
  const b: OcrBox[] = [
    B('세금계산서', 0.3, 0.04, 0.25),
    B('(공급받는자 보관용)', 0.56, 0.045, 0.2),
    B('책번호', 0.78, 0.03), B('3', 0.86, 0.03, 0.02), B('권', 0.89, 0.03, 0.02), B('12', 0.92, 0.03, 0.03), B('호', 0.96, 0.03, 0.02),
    B('일련번호', 0.78, 0.06), B('0045', 0.88, 0.06),
    B('공급자', 0.02, 0.15, 0.04),
    B('공급받는자', 0.5, 0.15, 0.04),
  ];
  if (opts.noLabels) {
    b.push(B('111-11-11119', 0.12, 0.11, 0.2), B('999-99-99997', 0.62, 0.11, 0.2));
  } else {
    b.push(
      B('등록번호', 0.06, 0.11), B('111-11-11119', 0.16, 0.11, 0.2),
      B('등록번호', 0.55, 0.11), B('999-99-99997', 0.65, 0.11, 0.2),
      B('상호(법인명)', 0.06, 0.14, 0.1), B('가나식자재', 0.17, 0.14, 0.12), B('성명', 0.3, 0.14, 0.05), B('김가나', 0.36, 0.14, 0.08),
      B('상호(법인명)', 0.55, 0.14, 0.1), B('시험카페', 0.66, 0.14, 0.12), B('성명', 0.8, 0.14, 0.05), B('홍길동', 0.86, 0.14, 0.08),
      B('사업장 주소', 0.06, 0.17, 0.1), B('서울 마포구 월드컵로 1', 0.17, 0.17, 0.3),
      B('사업장 주소', 0.55, 0.17, 0.1), B('서울 성동구 왕십리로 2', 0.66, 0.17, 0.3),
      B('업태', 0.06, 0.2, 0.05), B('도소매', 0.12, 0.2), B('종목', 0.3, 0.2, 0.05), B('식자재', 0.36, 0.2),
      B('업태', 0.55, 0.2, 0.05), B('음식점', 0.61, 0.2), B('종목', 0.8, 0.2, 0.05), B('커피', 0.86, 0.2),
    );
  }
  b.push(B('작성', 0.04, 0.25, 0.05), B('공급가액', 0.3, 0.25, 0.1), B('세액', 0.6, 0.25, 0.06), B('비고', 0.85, 0.25, 0.06));
  if (opts.digitCells) {
    // 자리마다 한 칸: 1 2 3 0 0 0 0 / 1 2 3 0 0 0
    b.push(B('2026', 0.02, 0.28, 0.06), B('11', 0.09, 0.28, 0.03), B('05', 0.13, 0.28, 0.03));
    [...'1230000'].forEach((d, i) => b.push(B(d, 0.25 + i * 0.03, 0.28, 0.02)));
    [...'123000'].forEach((d, i) => b.push(B(d, 0.58 + i * 0.03, 0.28, 0.02)));
  } else {
    b.push(B('2026', 0.02, 0.28, 0.06), B('11', 0.09, 0.28, 0.03), B('05', 0.13, 0.28, 0.03), B('1,230,000', 0.3, 0.28, 0.12), B('123,000', 0.6, 0.28, 0.1));
  }
  b.push(
    B('월', 0.02, 0.33, 0.02), B('일', 0.05, 0.33, 0.02), B('품목', 0.12, 0.33, 0.06), B('규격', 0.3, 0.33), B('수량', 0.4, 0.33), B('단가', 0.5, 0.33), B('공급가액', 0.62, 0.33, 0.1), B('세액', 0.78, 0.33, 0.06),
    B('11', 0.02, 0.36, 0.02), B('05', 0.05, 0.36, 0.02), B('원두 1kg', 0.12, 0.36, 0.12), B('10', 0.4, 0.36, 0.03), B('100,000', 0.5, 0.36, 0.1), B('1,000,000', 0.62, 0.36, 0.12), B('100,000', 0.78, 0.36, 0.1),
    B('11', 0.02, 0.39, 0.02), B('05', 0.05, 0.39, 0.02), B('우유', 0.12, 0.39, 0.06), B('1L', 0.3, 0.39, 0.03), B('50', 0.4, 0.39, 0.03), B('4,600', 0.5, 0.39, 0.08), B('230,000', 0.62, 0.39, 0.1), B('23,000', 0.78, 0.39, 0.08),
    B('합계금액', 0.02, 0.5, 0.1), B('현금', 0.2, 0.5, 0.05), B('수표', 0.3, 0.5, 0.05), B('어음', 0.4, 0.5, 0.05), B('외상미수금', 0.5, 0.5, 0.1), B('이 금액을 청구 함', 0.75, 0.5, 0.2),
    B('1,353,000', 0.02, 0.53, 0.12), B('1,353,000', 0.5, 0.53, 0.12),
  );
  return b;
}

